def description(term: str, mythology: str, kind: str, domains: str, summary: str, note: str, see_also: str) -> str:
    return "\n\n".join(
        [
            summary,
            note,
            (
                f"辞典的には、{term}は「{mythology}」の「{kind}」として引ける項目で、"
                f"主な手がかりは「{domains}」。単なる装備名ではなく、誰が持つのか、何を象徴するのか、"
                "どの戦いや儀礼で意味を持つのかを合わせて見ると輪郭がつかみやすい。"
            ),
            (
                f"関連語は「{see_also}」。創作や世界観設定では、攻撃力だけでなく、王権、誓約、神罰、"
                "守護、死者への通路、自然現象の制御といった役割を持つ道具として扱うと使いやすい。"
            ),
        ]
    )


def w(
    term: str,
    aliases: str,
    mythology: str,
    kind: str,
    domains: str,
    summary: str,
    note: str,
    see_also: str,
    *,
    reading: str = "",
    language: str = "",
    tags: str = "",
) -> dict[str, str]:
    return {
        "term": term,
        "reading": reading,
        "aliases": aliases,
        "language": language,
        "kind": kind,
        "mythology": mythology,
        "domains": domains,
        "tags": merge_multi_values("神話武器, 神器, 伝説の武具", mythology, tags, TAG),
        "summary": summary,
        "description": description(term, mythology, kind, domains, summary, note, see_also),
        "see_also": see_also,
        "sources": SOURCE_NOTE,
    }


